// AI Classification Logic
const ocrText = $input.first().json.responses[0].fullTextAnnotation?.text || '';

// Phân loại dựa trên keywords
let category = 'Khác';
let tags = [];

if (ocrText.toLowerCase().includes('hợp đồng') || ocrText.toLowerCase().includes('contract')) {
  category = 'Hợp đồng';
  tags.push('Hợp đồng');
}

if (ocrText.toLowerCase().includes('hóa đơn') || ocrText.toLowerCase().includes('invoice')) {
  category = 'Hóa đơn';
  tags.push('Hóa đơn');
}

if (ocrText.toLowerCase().includes('nhân sự') || ocrText.toLowerCase().includes('hr')) {
  tags.push('Nhân sự');
}

// Auto rename
const originalName = $input.first().json.body.file.name;
const date = new Date().toISOString().split('T')[0];
const newName = `${category}_${date}_${originalName}`;

return {
  originalName,
  newName,
  category,
  tags,
  ocrText: ocrText.substring(0, 500), // Limit text length
  confidence: 95
};
